  {"qtype": "选择题", "difficulty": 2, "stem": "【读后续写】读后续写两段首句通常已给出，第一段首句的作用是？（方法点拨）", "options": ["A. 随意写", "B. 承接上文、开启第一段情节", "C. 总结全文", "D. 列出原因"], "answer": "B", "analysis": "续写须以给出的段首句为起点，紧接原文情节合理展开，不能脱离上文另起炉灶。"},
  {"qtype": "填空题", "difficulty": 2, "stem": "【读后续写·动作描写】补全：He ____ down and carefully picked up the broken glass.（填动词，意为弯腰）", "options": [], "answer": "bent", "analysis": "bent down 弯腰，与 picked up 过去时一致。读后续写常用一系列连贯动作推动情节。"},
  {"qtype": "填空题", "difficulty": 3, "stem": "【读后续写·心理描写】补全：Her heart ____ wildly as she waited for the exam results.（填动词过去式，意为跳动）", "options": [], "answer": "beat", "analysis": "heart beat wildly 心狂跳，beat 的过去式为 beat。心理/身体反应是续写加分细节。"},
  {"qtype": "选择题", "difficulty": 3, "stem": "【读后续写·情感升华】续写结尾要做到？", "options": ["A. 突然结束", "B. 与原文呼应并有积极/感悟升华", "C. 引入全新人物", "D. 加入未出现的情节"], "answer": "B", "analysis": "续写结尾应与原文伏笔呼应，并在主题上有所升华（感悟、成长、温暖），使结构完整。"},
  {"qtype": "填空题", "difficulty": 2, "stem": "【读后续写·环境烘托】补全：The sun rose slowly, and the whole village was ____ in golden light.（填动词过去分词，意为沐浴）", "options": [], "answer": "bathed", "analysis": "be bathed in 沐浴在……中，用环境描写烘托人物心情，是续写常用技巧。"},
  {"qtype": "解答题", "difficulty": 3, "stem": "【读后续写】给定情境：小男孩迷路后哭泣，一位老人帮他找到妈妈。请用英语续写一句描写重逢的句子（含动作与情感，30词左右）。", "options": [], "answer": "Seeing his mother, the little boy rushed into her arms, tears of joy rolling down his cheeks, and thanked the old man again and again.", "analysis": "好的续写句含动作 rushed into arms、情感 tears of joy、以及与前文老人情节的呼应 thanked the old man，用独立主格增添画面感。"},
  {"qtype": "填空题", "difficulty": 3, "stem": "【读后续写·对话提示】补全：'Don't worry,' the policeman said ____ a smile on his face.（填介词）", "options": [], "answer": "with", "analysis": "with a smile on his face 面带微笑，with 复合结构作伴随状语，比 said happily 更生动。"},
  {"qtype": "选择题", "difficulty": 3, "stem": "【读后续写·语言】续写中不宜过多使用以下哪种语言？", "options": ["A. 动作链动词", "B. 神态心理描写", "C. 与情节无关的华丽长句与生僻词", "D. 与原文呼应的细节"], "answer": "C", "analysis": "续写重情节连贯与画面感，堆砌与生僻词和情节脱节，反而跑题；应围绕原文人物与伏笔展开。"},
  {"qtype": "填空题", "difficulty": 2, "stem": "【读后续写·动作描写】补全：He r____ as fast as he could in order to catch the leaving bus.（填动词过去式，意为跑）", "options": [], "answer": "ran", "analysis": "run（跑）的过去式为不规则变化 ran。"},
  {"qtype": "选择题", "difficulty": 2, "stem": "【读后续写】读后续写在情节上与原文应保持怎样的关系？", "options": ["A. 完全脱离原文，另起一个故事", "B. 紧扣原文人物、情节与伏笔合理续写", "C. 大段照抄原文句子", "D. 无视原文基调，强行改成悲剧"], "answer": "B", "analysis": "续写必须基于原文的人物、情节和伏笔合理发展，与原文基调保持一致，故选 B。"},
  {"qtype": "填空题", "difficulty": 3, "stem": "【读后续写·神态描写】补全：A big smile ____ on her face the moment she heard the good news.（填动词过去式，意为浮现、出现）", "options": [], "answer": "appeared", "analysis": "appear 出现；a smile appeared on one's face 某人脸上露出微笑，叙述过去用过去式 appeared。"},
  {"qtype": "选择题", "difficulty": 2, "stem": "【读后续写·连贯】让续写两段情节连贯、过渡自然，最有效的做法是？", "options": ["A. 每段更换一个主角", "B. 用时间或动作衔接词，并呼应所给段首句", "C. 尽量多用生僻词", "D. 不写结尾"], "answer": "B", "analysis": "借助时间、动作衔接词并呼应所给段首句，能保证两段情节连贯，故选 B。"},
  {"qtype": "填空题", "difficulty": 2, "stem": "【读后续写·情感描写】补全：Tears of ____ filled her eyes when she was finally reunited with her family.（填一个名词，意为喜悦）", "options": [], "answer": "joy", "analysis": "tears of joy 为固定搭配，意为喜悦的泪水，重逢场景用 joy。"},
  {"qtype": "选择题", "difficulty": 3, "stem": "【读后续写·描写】下列句子最能表现人物「紧张」心理的是？", "options": ["A. He slept soundly all night.", "B. His hands trembled and his heart beat fast.", "C. He ate a big meal happily.", "D. The sky was clear and blue."], "answer": "B", "analysis": "双手颤抖、心跳加快是紧张的典型动作与生理反应，故选 B；其余分别写熟睡、开心用餐和环境。"},
  {"qtype": "填空题", "difficulty": 2, "stem": "【读后续写·环境描写】补全：It was getting dark, and a cold wind was b____ hard.（填动词 -ing 形式，意为吹）", "options": [], "answer": "blowing", "analysis": "过去进行时结构为 was/were + doing；blow hard 指风刮得猛烈，故填 blowing。"},
